command -v fzf >/dev/null 2>&1 && eval "$(fzf --bash)"
command -v zoxide >/dev/null 2>&1 && eval "$(zoxide init bash)"
command -v starship >/dev/null 2>&1 && eval "$(starship init bash)"

# Completions generated by `mise run setup:completions` (gopass, fnox, ...).
for __dotfiles_completion in "$HOME"/.local/share/bash/completions/*.bash; do
  [ -r "$__dotfiles_completion" ] && . "$__dotfiles_completion"
done
unset __dotfiles_completion
